/// Appends `entry` on a new line and gives the log back.
fn append_entry(mut log: String, entry: &str) -> String {
    if !log.is_empty() {
        log.push('\n');
    }
    log.push_str(entry);
    log
}

/// Gives the log back together with its number of lines.
fn count_lines(log: String) -> (String, usize) {
    let lines = log.lines().count();
    (log, lines)
}

fn main() {
    let log = String::from("day 1: set sail");
    let log = append_entry(log, "day 2: storm");
    let (log, lines) = count_lines(log);
    println!("{lines} lines:\n{log}");
}

