mod hidden_tests {
    use super::*;

    #[test]
    fn append_to_existing_log_adds_a_line() {
        assert_eq!(append_entry(String::from("a"), "b"), "a\nb");
    }

    #[test]
    fn append_to_empty_log_has_no_leading_newline() {
        assert_eq!(append_entry(String::new(), "first"), "first");
    }

    #[test]
    fn appends_chain() {
        let log = append_entry(append_entry(String::new(), "x"), "y");
        assert_eq!(append_entry(log, "z"), "x\ny\nz");
    }

    #[test]
    fn count_lines_returns_log_unchanged() {
        let (log, n) = count_lines(String::from("one\ntwo\nthree"));
        assert_eq!(log, "one\ntwo\nthree");
        assert_eq!(n, 3);
    }

    #[test]
    fn empty_log_has_zero_lines() {
        assert_eq!(count_lines(String::new()), (String::new(), 0));
    }
}

