fn manifest(names: Vec<String>) -> String {
    if names.is_empty() {
        return String::from("(empty)");
    }
    let mut out = String::new();
    for (i, name) in names.into_iter().enumerate() {
        if i > 0 {
            out.push('\n');
        }
        out.push_str(&format!("{}. {}", i + 1, name));
    }
    out
}

fn main() {
    let crew = vec![String::from("Ann"), String::from("Bo")];
    println!("{}", manifest(crew));
}

