challenges.starter:
use std::io::{self, Read};

// One entry per non-empty, trimmed line.
fn entries(text: String) -> Vec<String> {
    let mut out = Vec::new();
    for line in text.lines() {
        if !line.trim().is_empty() {
            out.push(line.trim().to_string());
        }
    }
    out
}

fn report(items: Vec<String>) -> String {
    format!("{} entries, first: {}", items.len(), items[0])
}

// The first entry with the most bytes, or "none".
fn longest(items: Vec<String>) -> String {
    let mut best = String::from("none");
    let mut best_len = 0;
    for item in items {
        if item.len() > best_len {
            best_len = item.len();
            best = item;
        }
    }
    best
}

fn main() {
    let mut text = String::new();
    io::stdin().read_to_string(&mut text).unwrap();
    let items = entries(text);
    println!("{}", report(items));
    println!("raw bytes: {}", text.len());
    for item in items {
        println!("- {item}");
    }
    println!("longest: {}", longest(items));
}

